+    // issue this copy. A disabled store must not advance any thread's queue.
+    auto &commit = *ptx.create("cp.async.bulk.commit_group");
+    commit().predicate(adaptor.getPred());
+    ptx.launch(rewriter, loc, void_ty(op.getContext()));
+    rewriter.eraseOp(op);
+    return success();
+  }
+};
